<?php
declare(strict_types=1);

/** Centraliza o catalogo de menus sem mover autorizacoes dos tenants. */
$env=[];
foreach(file(__DIR__.'/../.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$key,$value]=explode('=',$line,2);$env[trim($key)]=trim(trim($value),"\"'");}
$options=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC];
function db(array $env,string $prefix,string $schema,array $options):PDO{return new PDO('mysql:host='.$env[$prefix.'_DB_HOST'].';port='.$env[$prefix.'_DB_PORT'].';dbname='.$schema.';charset=utf8mb4',$env[$prefix.'_DB_USERNAME'],$env[$prefix.'_DB_PASSWORD'],$options);}
function migration(PDO $pdo,string $database,int $quantity,array $details):void{$sql="INSERT INTO registros_migracao(codigo_migracao,origem,destino,tipo,versao,status,quantidade_registros,iniciada_em,concluida_em,detalhes) VALUES('CATALOGO_MENUS_UNIVERSAL','gmodelo_dbp;gmodelo2_dbp;gatlas_dbp','guniversal_dbp.menus;tenants.perfil_menus;tenants.permissoes','ESTRUTURA','0.160.0','CONCLUIDA',?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?) ON DUPLICATE KEY UPDATE status='CONCLUIDA',quantidade_registros=VALUES(quantidade_registros),concluida_em=CURRENT_TIMESTAMP,detalhes=VALUES(detalhes)";$stmt=$pdo->prepare($sql);$stmt->execute([$quantity,json_encode(['tenant'=>$database]+$details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}

$universal=db($env,'GUNIVERSAL',$env['GUNIVERSAL_DB_DATABASE']??'guniversal_dbp',$options);
$tenants=['gmodelo_dbp','gmodelo2_dbp','gatlas_dbp'];
$tenantPdos=[];$catalog=[];
foreach($tenants as $database){$pdo=db($env,'GPT',$database,$options);$tenantPdos[$database]=$pdo;foreach($pdo->query('SELECT codmenu,codmenu_pai,modulo,codigo,label,label_pt,label_en,label_es,url,nivel,ordem,ativo FROM menus ORDER BY codmenu') as $row){$code=(string)$row['codigo'];if(isset($catalog[$code])&&(int)$catalog[$code]['codmenu']!==(int)$row['codmenu'])throw new RuntimeException('Conflito de codmenu para '.$code);if(!isset($catalog[$code]))$catalog[$code]=$row;}}

$universal->exec("CREATE TABLE IF NOT EXISTS menus (codmenu BIGINT UNSIGNED NOT NULL,codmenu_pai BIGINT UNSIGNED NULL,modulo VARCHAR(100) NOT NULL,codigo VARCHAR(100) NOT NULL,label VARCHAR(150) NOT NULL,label_pt VARCHAR(150) NULL,label_en VARCHAR(150) NULL,label_es VARCHAR(150) NULL,url VARCHAR(255) NULL,nivel TINYINT UNSIGNED NOT NULL DEFAULT 1,ordem INT NOT NULL DEFAULT 0,icone VARCHAR(100) NULL,ativo TINYINT(1) NOT NULL DEFAULT 1,PRIMARY KEY(codmenu),UNIQUE KEY uk_menus_codigo(codigo),KEY ix_menus_pai(codmenu_pai)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci");
$insert=$universal->prepare('INSERT INTO menus(codmenu,codmenu_pai,modulo,codigo,label,label_pt,label_en,label_es,url,nivel,ordem,icone,ativo) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE codmenu_pai=VALUES(codmenu_pai),modulo=VALUES(modulo),label=VALUES(label),label_pt=VALUES(label_pt),label_en=VALUES(label_en),label_es=VALUES(label_es),url=VALUES(url),nivel=VALUES(nivel),ordem=VALUES(ordem),ativo=VALUES(ativo)');
foreach($catalog as $row)$insert->execute([(int)$row['codmenu'],$row['codmenu_pai']!==null?(int)$row['codmenu_pai']:null,(string)$row['modulo'],(string)$row['codigo'],(string)$row['label'],$row['label_pt'],$row['label_en'],$row['label_es'],$row['url'],(int)$row['nivel'],(int)$row['ordem'],null,(int)$row['ativo']]);

$parent=(int)($universal->query("SELECT codmenu FROM menus WHERE codigo='ADMINISTRACAO' LIMIT 1")->fetchColumn()?:0);if(!$parent)throw new RuntimeException('Menu pai ADMINISTRACAO nao encontrado.');
$helpId=(int)($universal->query("SELECT codmenu FROM menus WHERE codigo='ADMINISTRACAO_HELPDESK' LIMIT 1")->fetchColumn()?:0);if(!$helpId)$helpId=(int)$universal->query('SELECT COALESCE(MAX(codmenu),0)+1 FROM menus')->fetchColumn();
$helpOrder=(int)($universal->query("SELECT COALESCE(MAX(ordem),0)+1 FROM menus WHERE codmenu_pai=".$parent)->fetchColumn()?:1);
$insert->execute([$helpId,$parent,'ADMINISTRACAO','ADMINISTRACAO_HELPDESK','Help Desk','Help Desk','Help Desk','Help Desk','/principal/administracao_helpdesk.php',2,$helpOrder,'bi-headset',1]);

$viewSql="CREATE OR REPLACE VIEW vw_permissoes_grid AS SELECT p.codpermissao,p.codperfil,pf.codigo AS perfil_codigo,p.codmenu,m.codigo AS menu_codigo,m.label_pt AS menu_label,p.pode_incluir,p.pode_visualizar,p.pode_visualizar_total,p.pode_editar,p.pode_excluir,p.pode_exportar_excel,p.pode_gerar_pdf FROM permissoes p JOIN perfis pf ON pf.codperfil=p.codperfil JOIN guniversal_dbp.menus m ON m.codmenu=p.codmenu";
$summary=['catalogo_menus'=>count($catalog),'helpdesk_codmenu'=>$helpId,'tenants'=>[]];
$dropAuthorizationMenuFks=function(PDO $pdo,string $database):void{foreach(['perfil_menus','permissoes'] as $table){$fk=$pdo->prepare("SELECT constraint_name FROM information_schema.key_column_usage WHERE table_schema=? AND table_name=? AND column_name='codmenu' AND referenced_table_name='menus'");$fk->execute([$database,$table]);foreach($fk->fetchAll(PDO::FETCH_COLUMN) as $constraint)$pdo->exec('ALTER TABLE `'.$table.'` DROP FOREIGN KEY `'.$constraint.'`');}};
$dropAuthorizationMenuFks($tenantPdos['gmodelo_dbp'],'gmodelo_dbp');
$dropAuthorizationMenuFks($tenantPdos['gmodelo2_dbp'],'gmodelo2_dbp');
$dropAuthorizationMenuFks($tenantPdos['gatlas_dbp'],'gatlas_dbp');
foreach($tenantPdos as $database=>$pdo){$pdo->exec($viewSql);$codes=$database==='gatlas_dbp'?['ADMINISTRADOR','FORNECEDOR']:['ADMINISTRADOR'];$added=0;$profileStmt=$pdo->prepare('SELECT codperfil FROM perfis WHERE codigo=? AND ativo=1 LIMIT 1');$perm=$pdo->prepare('INSERT INTO perfil_menus(codperfil,codmenu,pode_incluir,pode_visualizar,pode_editar,pode_excluir,pode_exportar_excel,pode_gerar_pdf) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE pode_incluir=VALUES(pode_incluir),pode_visualizar=VALUES(pode_visualizar),pode_editar=VALUES(pode_editar),pode_excluir=VALUES(pode_excluir),pode_exportar_excel=VALUES(pode_exportar_excel),pode_gerar_pdf=VALUES(pode_gerar_pdf)');$permMirror=$pdo->prepare('INSERT INTO permissoes(codperfil,codmenu,pode_incluir,pode_visualizar,pode_editar,pode_excluir,pode_exportar_excel,pode_gerar_pdf) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE pode_incluir=VALUES(pode_incluir),pode_visualizar=VALUES(pode_visualizar),pode_editar=VALUES(pode_editar),pode_excluir=VALUES(pode_excluir),pode_exportar_excel=VALUES(pode_exportar_excel),pode_gerar_pdf=VALUES(pode_gerar_pdf)');foreach($codes as $code){$profileStmt->execute([$code]);$profile=(int)$profileStmt->fetchColumn();if(!$profile)continue;$values=[$profile,$helpId,1,1,1,1,1,1];$perm->execute($values);$permMirror->execute($values);$added++;}$summary['tenants'][$database]=['perfis_helpdesk'=>$added];migration($pdo,$database,$added,$summary['tenants'][$database]);}
echo json_encode($summary,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL;
